<template>
  <ManagementPageScaffold title="مدیریت مجله" subtitle="مقاله بسازید، زمان انتشار را مدیریت کنید و محصولات منو را به نوشته پیوند دهید.">
    <template #actions><button class="secondary-btn" type="button" @click="loadPosts" :disabled="loading">بروزرسانی</button><button class="primary-btn" type="button" @click="newPost">مقالهٔ جدید</button></template>
    <div class="blog-manager">
      <ManagementSurfaceCard title="مقاله‌ها" subtitle="پیش‌نویس‌ها و نوشته‌های منتشرشده">
        <div class="manager-toolbar"><input class="input" v-model="search" placeholder="جستجوی عنوان..." @input="loadPosts"><span>{{ filteredPosts.length }} مقاله</span></div>
        <p v-if="loading" class="muted">در حال بارگذاری...</p><p v-else-if="!filteredPosts.length" class="empty">هنوز مقاله‌ای ثبت نشده. اولین مقاله را بسازید.</p>
        <button v-for="post in filteredPosts" :key="post.name" class="post-row" :class="{selected:form?.name===post.name}" type="button" @click="openPost(post)"><span class="post-row__image"><img v-if="post.cover_image" :src="post.cover_image" :alt="''"><FileText v-else :size="20"/></span><span class="post-row__title"><b>{{ post.title }}</b><small>{{ post.category || 'بدون دسته' }} · {{ post.is_published?'منتشرشده':'پیش‌نویس' }}</small></span><ChevronLeft :size="17"/></button>
      </ManagementSurfaceCard>
      <ManagementSurfaceCard :title="form?.name?'ویرایش مقاله':'مقالهٔ تازه'" subtitle="عنوان، متن و محصولات مرتبط را در یک فرم کامل کنید">
        <div v-if="form" class="editor-form">
          <div class="field-grid">
            <label>عنوان مقاله <input class="input" v-model.trim="form.title" placeholder="مثلاً راهنمای انتخاب قهوهٔ تازه"></label>
            <label>نشانی صفحه <input class="input" v-model.trim="form.route" dir="ltr" placeholder="fresh-coffee-guide"></label>
            <label>دسته‌بندی <input class="input" v-model.trim="form.category" placeholder="راهنمای آشپزی"></label>
            <label>زمان مطالعه (دقیقه) <input class="input" type="number" min="1" v-model.number="form.read_time"></label>
            <label class="wide">خلاصهٔ مقاله <textarea class="input" rows="2" v-model.trim="form.excerpt" placeholder="در چند جمله به خواننده بگویید این مقاله دربارهٔ چیست."></textarea></label>
            <label class="wide">تصویر شاخص <div class="cover-field"><input class="input" v-model.trim="form.cover_image" dir="ltr" placeholder="/files/blog-cover.jpg"><label class="secondary-btn upload-button">انتخاب تصویر<input type="file" accept="image/*" hidden @change="uploadCover"></label></div><img v-if="form.cover_image" class="cover-preview" :src="form.cover_image" alt="پیش‌نمایش تصویر شاخص"></label>
          </div>
          <label class="form-label">متن مقاله</label><BlogRichTextEditor :key="form.name||'new'" v-model="form.body_html" />
          <div class="products-editor"><div class="products-head"><div><h3>محصولات مرتبط</h3><p>چند محصول را انتخاب کنید تا در کنار متن مقاله نمایش داده شوند.</p></div><div class="product-search"><input class="input" v-model="productQuery" placeholder="جستجوی محصول..." @input="searchProducts"><div v-if="productResults.length" class="product-results"><button v-for="item in productResults" :key="item.item_code" type="button" @click="addProduct(item)"><img v-if="item.image" :src="item.image" alt=""><span><b>{{ item.item_name }}</b><small>{{ item.item_code }}</small></span><Plus :size="16"/></button></div></div></div>
            <div v-if="form.related_products.length" class="linked-products"><div v-for="(item,index) in form.related_products" :key="item.item_code" class="linked-product"><img v-if="item.image_override||item.image" :src="item.image_override||item.image" alt=""><Package v-else :size="21"/><span><b>{{ item.custom_label||item.item_name||item.item_code }}</b><small>{{ item.item_code }}</small></span><button type="button" title="حذف محصول" @click="form.related_products.splice(index,1)"><X :size="17"/></button></div></div><p v-else class="empty-inline">هنوز محصولی به مقاله پیوند نشده است.</p>
          </div>
          <div class="publish-row"><label><input type="checkbox" v-model="form.is_published"> انتشار مقاله</label><label><input type="checkbox" v-model="form.is_featured"> نمایش به‌عنوان مقالهٔ ویژه</label></div>
          <div class="field-grid seo-grid"><label>عنوان سئو <input class="input" v-model.trim="form.meta_title"></label><label>توضیحات سئو <input class="input" v-model.trim="form.meta_description"></label></div>
          <p v-if="error" class="error">{{ error }}</p><p v-if="message" class="success-msg">{{ message }}</p>
          <div class="form-actions"><button class="primary-btn" type="button" @click="save" :disabled="saving">{{ saving?'در حال ذخیره...':'ذخیرهٔ مقاله' }}</button><a v-if="form.is_published&&form.route" class="secondary-btn" :href="`/blog/${encodeURIComponent(form.route)}`" target="_blank">پیش‌نمایش</a><button v-if="form.name" class="secondary-btn danger" type="button" @click="removePost">حذف مقاله</button></div>
        </div><div v-else class="empty">برای شروع، یک مقالهٔ جدید بسازید یا از فهرست انتخاب کنید.</div>
      </ManagementSurfaceCard>
    </div>
  </ManagementPageScaffold>
</template>
<script setup>
import { computed,onMounted,ref } from 'vue'
import { ChevronLeft,FileText,Package,Plus,X } from 'lucide-vue-next'
import ManagementPageScaffold from '@/components/management/ManagementPageScaffold.vue'
import ManagementSurfaceCard from '@/components/management/ManagementSurfaceCard.vue'
import BlogRichTextEditor from '@/components/blog/BlogRichTextEditor.vue'
import { deleteManagementBlogPost,getManagementBlogPost,getManagementBlogPosts,saveManagementBlogPost,searchManagementBlogProducts,uploadFileToFrappe } from '@/utils/api'
const posts=ref([]),form=ref(null),loading=ref(false),saving=ref(false),search=ref(''),productQuery=ref(''),productResults=ref([]),error=ref(''),message=ref('')
const filteredPosts=computed(()=>posts.value.filter(p=>!search.value||p.title?.toLowerCase().includes(search.value.toLowerCase())))
function blank(){return {title:'',route:'',category:'',excerpt:'',cover_image:'',body_html:'',related_products:[],is_published:false,is_featured:false,read_time:3,meta_title:'',meta_description:''}}
async function loadPosts(){loading.value=true;try{posts.value=await getManagementBlogPosts({search:search.value})||[]}catch(e){error.value=e.message||'دریافت مقاله‌ها ممکن نشد.'}finally{loading.value=false}}
function newPost(){form.value=blank();error.value='';message.value=''}
async function openPost(row){try{form.value=await getManagementBlogPost({name:row.name});form.value.related_products=(form.value.related_products||[]).map(x=>({...x,item_name:x.item_name||x.title,image:x.image}));error.value='';message.value=''}catch(e){error.value=e.message}}
function slugify(){if(!form.value.route)form.value.route=String(form.value.title||'').trim().toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-').replace(/^-|-$/g,'')}
async function save(){error.value='';message.value='';slugify();if(!form.value.title||!form.value.route){error.value='عنوان و نشانی مقاله را وارد کنید.';return}saving.value=true;try{const result=await saveManagementBlogPost({payload:form.value});form.value=result;await loadPosts();message.value='مقاله با موفقیت ذخیره شد.'}catch(e){error.value=e.message||'ذخیره مقاله ناموفق بود.'}finally{saving.value=false}}
async function removePost(){if(!window.confirm('این مقاله برای همیشه حذف شود؟'))return;try{await deleteManagementBlogPost({name:form.value.name});form.value=null;await loadPosts()}catch(e){error.value=e.message}}
let searchTimer;async function searchProducts(){clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{try{productResults.value=await searchManagementBlogProducts({query:productQuery.value})||[]}catch{productResults.value=[]}},220)}
function addProduct(item){if(form.value.related_products.some(x=>x.item_code===item.item_code))return;form.value.related_products.push({...item,custom_label:'',note:'',image_override:''});productResults.value=[];productQuery.value=''}
async function uploadCover(event){const file=event.target.files?.[0];if(!file)return;try{const result=await uploadFileToFrappe(file,{isPrivate:false});form.value.cover_image=result.file_url}catch(e){error.value=e.message||'آپلود تصویر انجام نشد.'}finally{event.target.value=''}}
onMounted(loadPosts)
</script>
<style scoped>
.blog-manager{display:grid;grid-template-columns:minmax(280px,.72fr) minmax(0,1.7fr);gap:1rem;align-items:start}.manager-toolbar{display:flex;align-items:center;gap:.7rem;margin-bottom:.6rem}.manager-toolbar .input{flex:1}.manager-toolbar>span{white-space:nowrap;color:var(--mg-text-muted);font-size:.82rem}.post-row{display:flex;width:100%;align-items:center;gap:.7rem;padding:.72rem .25rem;border:0;border-top:1px solid var(--mg-border-light);background:transparent;color:var(--mg-text-main);text-align:right;cursor:pointer}.post-row.selected{background:color-mix(in srgb,var(--mg-action-primary) 8%,transparent)}.post-row__image{display:grid;place-items:center;flex:none;width:48px;height:48px;overflow:hidden;border-radius:10px;background:var(--mg-bg-page);color:var(--mg-action-primary)}.post-row__image img{width:100%;height:100%;object-fit:cover}.post-row__title{display:grid;gap:.24rem;flex:1;min-width:0}.post-row__title b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.post-row__title small{color:var(--mg-text-muted)}.editor-form{display:grid;gap:1rem}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem}.field-grid label,.form-label{display:grid;gap:.4rem;color:var(--mg-text-main);font-size:.85rem;font-weight:800}.field-grid .wide{grid-column:1/-1}.field-grid .input{width:100%;min-height:42px}.field-grid textarea{resize:vertical}.cover-field{display:flex;gap:.5rem}.cover-field .input{flex:1}.upload-button{display:grid;place-items:center;min-height:42px;white-space:nowrap;cursor:pointer}.cover-preview{width:min(100%,360px);height:160px;object-fit:cover;border-radius:10px}.products-editor{padding:1rem;border:1px solid var(--mg-border-light);border-radius:14px;background:var(--mg-bg-page)}.products-head{display:flex;align-items:start;justify-content:space-between;gap:1rem}.products-head h3{font-size:.95rem;margin:0}.products-head p{font-size:.8rem;color:var(--mg-text-muted);margin:.2rem 0}.product-search{position:relative;width:min(320px,100%)}.product-results{position:absolute;z-index:3;top:calc(100% + 4px);right:0;left:0;max-height:260px;overflow:auto;border:1px solid var(--mg-border-light);border-radius:10px;background:var(--mg-bg-surface);box-shadow:var(--mg-shadow-sm)}.product-results button{display:flex;align-items:center;gap:.6rem;width:100%;padding:.55rem;border:0;border-bottom:1px solid var(--mg-border-light);background:transparent;text-align:right;color:var(--mg-text-main);cursor:pointer}.product-results img{width:38px;height:38px;object-fit:cover;border-radius:8px}.product-results span{display:grid;flex:1}.product-results small,.linked-product small{color:var(--mg-text-muted)}.linked-products{display:grid;gap:.5rem;margin-top:.85rem}.linked-product{display:flex;align-items:center;gap:.65rem;padding:.55rem;border:1px solid var(--mg-border-light);border-radius:10px;background:var(--mg-bg-surface)}.linked-product>img{width:42px;height:42px;object-fit:cover;border-radius:8px}.linked-product>span{display:grid;flex:1}.linked-product>button{border:0;background:transparent;color:var(--mg-text-muted);cursor:pointer}.empty-inline,.empty{padding:1.2rem;color:var(--mg-text-muted);text-align:center}.publish-row{display:flex;flex-wrap:wrap;gap:1rem}.publish-row label{display:flex;align-items:center;gap:.45rem;color:var(--mg-text-main);font-size:.85rem}.seo-grid{padding-top:.8rem;border-top:1px solid var(--mg-border-light)}.form-actions{display:flex;gap:.6rem;flex-wrap:wrap}.form-actions a{text-decoration:none}.danger{color:#b44732}.error{color:#b42318}.success-msg{color:#28744d}@media(max-width:920px){.blog-manager{grid-template-columns:1fr}}@media(max-width:600px){.field-grid{grid-template-columns:1fr}.field-grid .wide{grid-column:auto}.products-head{flex-direction:column}.product-search{width:100%}.cover-field{flex-direction:column}}
</style>
